module greedy_tower(\n    input clk,\n    input rst_n,\n    input start,\n    input [19:0] m,\n    output reg [4:0] blocks,\n    output reg [19:0] volume,\n    output reg done\n);\n\n    // State definitions\n    localparam [3:0] \n        IDLE          = 4'd0,\n        INIT          = 4'd1,\n        COMPUTE_CUBE  = 4'd2,\n        POST_CUBE     = 4'd3,\n        PUSH_PATH_B   = 4'd4,\n        CHECK_BEST    = 4'd5,\n        POP_STACK     = 4'd6,\n        DONE_STATE    = 4'd7;\n\n    reg [3:0] state, next_state;\n    \n    // Cube root search registers\n    reg [6:0] cr_low, cr_high, cr_mid;\n    reg [2:0] cr_count;\n    wire [19:0] cr_mid_cubed = cr_mid * cr_mid * cr_mid;\n    reg [6:0] a_value;\n\n    // Stack storage\n    reg [19:0] stack_m [0:17];\n    reg [19:0] stack_v [0:17];\n    reg [4:0] stack_b [0:17];\n    reg [5:0] stack_ptr;\n\n    // Current working state\n    reg [19:0] current_m;\n    reg [19:0] current_vol;\n    reg [4:0] current_blk;\n\n    // Best found values\n    reg [19:0] best_vol;\n    reg [4:0] best_blk;\n\n    // Safety timeout\n    reg [9:0] cycle_cnt;\n    \n    integer i;  // Loop variable for reset\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Reset all registers\n            state <= IDLE;\n            done <= 1'b0;\n            blocks <= 5'd0;\n            volume <= 20'd0;\n            stack_ptr <= 6'd0;\n            cycle_cnt <= 10'd0;\n            best_vol <= 20'd0;\n            best_blk <= 5'd0;\n            \n            // Initialize array to zero\n            for (i = 0; i < 18; i = i + 1) begin\n                stack_m[i] <= 20'd0;\n                stack_v[i] <= 20'd0;\n                stack_b[i] <= 5'd0;\n            end\n        end else begin\n            cycle_cnt <= cycle_cnt + 10'd1;\n            state <= next_state;\n\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    cycle_cnt <= 10'd0;\n                    if (start) begin\n                        next_state <= INIT;\n                    end else begin\n                        next_state <= IDLE;\n                    end\n                end\n\n                INIT: begin\n                    current_m <= m;\n                    current_vol <= 20'd0;\n                    current_blk <= 5'd0;\n                    stack_m[0] <= m;\n                    stack_v[0] <= 20'd0;\n                    stack_b[0] <= 5'd0;\n                    stack_ptr <= 6'd1;\n                    best_vol <= 20'd0;\n                    best_blk <= 5'd0;\n                    next_state <= COMPUTE_CUBE;\n                end\n\n                COMPUTE_CUBE: begin\n                    if (cycle_cnt[2:0] == 3'd0) begin\n                        cr_low <= 7'd0;\n                        cr_high <= 7'd100;\n                        cr_count <= 3'd0;\n                        cr_mid <= 7'd50;\n                    end else begin\n                        if (cr_count < 3'd7) begin\n                            cr_mid <= (cr_low + cr_high) / 2;\n                            if (cr_mid_cubed <= current_m) begin\n                                cr_low <= cr_mid + 7'd1;\n                            end else begin\n                                cr_high <= cr_mid - 7'd1;\n                            end\n                            cr_count <= cr_count + 3'd1;\n                        end else begin\n                            a_value <= cr_high;\n                            next_state <= POST_CUBE;\n                        end\n                    end\n                end\n\n                POST_CUBE: begin\n                    if (a_value >= 7'd1) begin\n                        next_state <= PUSH_PATH_B;\n                    end else begin\n                        next_state <= CHECK_BEST;\n                    end\n                end\n\n                PUSH_PATH_B: begin\n                    // Calculate path B values\n                    reg [19:0] pathB_vol = current_vol + ((a_value - 7'd1) * (a_value - 7'd1) * (a_value - 7'd1));\n                    reg [4:0] pathB_blk = current_blk + 5'd1;\n                    reg [19:0] pathB_m = (3 * a_value * (a_value - 7'd1)) + 20'd1;\n\n                    // Push path B to stack if blocks <= 18\n                    if (pathB_blk <= 5'd18 && stack_ptr < 6'd17) begin\n                        stack_m[stack_ptr] <= pathB_m;\n                        stack_v[stack_ptr] <= pathB_vol;\n                        stack_b[stack_ptr] <= pathB_blk;\n                        stack_ptr <= stack_ptr + 6'd1;\n                    end\n\n                    // Update current state for path A\n                    current_m <= current_m - (a_value * a_value * a_value);\n                    current_vol <= current_vol + (a_value * a_value * a_value);\n                    current_blk <= current_blk + 5'd1;\n\n                    // Check if path A is valid\n                    if (current_blk < 5'd17) begin\n                        next_state <= COMPUTE_CUBE;\n                        cycle_cnt[2:0] <= 3'd0;\n                    end else begin\n                        next_state <= CHECK_BEST;\n                    end\n                end\n\n                CHECK_BEST: begin\n                    // Update best solution\n                    if (current_blk > best_blk ||\n                       (current_blk == best_blk && current_vol > best_vol)) begin\n                        best_blk <= current_blk;\n                        best_vol <= current_vol;\n                    end\n                    \n                    if (stack_ptr != 6'd0) begin\n                        next_state <= POP_STACK;\n                    end else begin\n                        next_state <= DONE_STATE;\n                    end\n                end\n\n                POP_STACK: begin\n                    stack_ptr <= stack_ptr - 6'd1;\n                    current_m <= stack_m[stack_ptr - 6'd1];\n                    current_vol <= stack_v[stack_ptr - 6'd1];\n                    current_blk <= stack_b[stack_ptr - 6'd1];\n                    next_state <= COMPUTE_CUBE;\n                    cycle_cnt[2:0] <= 3'd0;\n                end\n\n                DONE_STATE: begin\n                    blocks <= best_blk;\n                    volume <= best_vol;\n                    done <= 1'b1;\n                    next_state <= IDLE;\n                end\n\n                default: next_state <= IDLE;\n            endcase\n\n            // Safety timeout\n            if (cycle_cnt >= 10'd1000) begin\n                next_state <= DONE_STATE;\n            end\n        end\n    end\n\nendmodule